import itertools
def search(A_out, A_in=None):
    n=len(A_out)
    sols=[]
    for sr in (-1,1):
        for sc in (-1,1):
            for ar in range(-n,n):
                for ac in range(-n,n):
                    # ring(i,j)=max(sr*i+ar, sc*j+ac); drop invalid (negative ring) but allow all
                    ring={}
                    ok=True
                    for i in range(n):
                        for j in range(n):
                            r=sr*i+ar
                            q=sc*j+ac
                            rr=max(r,q)
                            if rr<0: continue
                            if rr in ring and ring[rr]!=A_out[i][j]: ok=False;break
                            ring[rr]=A_out[i][j]
                        if not ok:break
                    if not ok:continue
                    K=max(ring)+1
                    c={}; cons=True
                    for rr,v in ring.items():
                        if c.get(rr%K)!=v: cons=False;break
                        c[rr%K]=v
                    if not cons:continue
                    pred=[[c[max(sr*i+ar,sc*j+ac)%K] for j in range(n)] for i in range(n)]
                    if pred==[r[:] for r in A_out]:
                        sols.append((sr,sc,ar,ac,K,list(sorted(c.values()))))
    return sols
